model.en:
type Stringify<T> = { [K in keyof T]: string };
// Stringify<[number, number]>  // ^? [string, string]

// Drops the extra K parameter and maps directly over keyof T so the constraint is exactly keyof T (homomorphic).

model.ru:
type Stringify<T> = { [K in keyof T]: string };
// Stringify<[number, number]>  // ^? [string, string]

// Убирает лишний параметр K и отображает напрямую по keyof T, чтобы ограничение было в точности keyof T (гомоморфно).

model.en:
type MyPick<T, K extends keyof T> = { [P in K]: T[P] };
// MyPick<{ a: number; b: string; c: boolean }, 'a' | 'c'>  // ^? { a: number; c: boolean }

// Maps over P in K (the chosen subset) and uses T[P] for each value, yielding { a: number; c: boolean }.

